"""Standalone personal-workspace page; facts are fetched from server-side APIs only."""


def cabinet_html() -> str:
    return r"""<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MAVIS · Моя работа</title>
<style>
:root{--ink:#123c56;--muted:#6c8798;--line:#d3e5ec;--bg:#eff6f8;--teal:#008c8e;--teal-2:#daf5f1;--navy:#0d5a7d;--danger:#b44d54;--white:#fff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(115deg,#f4fafb,#e9f4f7);color:var(--ink);font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{max-width:1520px;margin:auto;padding:24px;display:grid;grid-template-columns:270px minmax(0,1fr);gap:20px}.rail,.panel,.hero{background:var(--white);border:1px solid var(--line);box-shadow:0 12px 34px #0e49620d}.rail{height:max-content;position:sticky;top:16px;padding:22px;border-radius:24px}.brand,.eyebrow{font-size:11px;font-weight:900;letter-spacing:.13em;text-transform:uppercase;color:#518196}.avatar{width:64px;height:64px;margin:24px 0 11px;border-radius:18px;display:grid;place-items:center;background:linear-gradient(135deg,#bdf0e8,#c5e9fc);font-size:22px;font-weight:900;color:#08697c}.rail h2{margin:0;font-size:20px}.muted{margin:6px 0;color:var(--muted);font-size:13px;line-height:1.45}.identity{display:inline-flex;margin-top:9px;padding:6px 10px;border-radius:99px;background:#e4f6f3;color:#007b78;font-size:12px;font-weight:800}.nav{display:grid;gap:5px;margin:27px 0}.nav button{border:0;background:transparent;text-align:left;padding:10px;border-radius:10px;color:#547687;font:700 14px inherit;cursor:pointer}.nav button[aria-selected=true],.nav button:hover{background:var(--teal-2);color:#076b75}.hero{border-radius:24px;padding:25px 28px;display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.hero h1{margin:7px 0 0;font-size:34px;letter-spacing:-.04em}.actions{display:flex;flex-wrap:wrap;gap:8px}.button,.select{border:1px solid #bcd6e0;background:#fff;color:#1b4f6b;border-radius:11px;padding:10px 12px;font:800 14px inherit}.button{cursor:pointer}.button.primary{background:var(--teal);border-color:var(--teal);color:#fff}.select{max-width:240px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.kpi{min-height:116px;padding:17px;border:1px solid var(--line);border-radius:18px;background:#fff}.kpi.score{background:linear-gradient(135deg,#d9f7f1,#f8fffe);border-color:#9fded8}.kpi small{display:block;color:var(--muted);font-weight:800}.kpi b{display:block;margin:8px 0 4px;font-size:27px;letter-spacing:-.04em}.kpi span{font-size:12px;color:#607f91}.tabs{display:flex;gap:8px;margin:18px 0}.tabs button{border:1px solid #c7dde6;background:#fff;border-radius:99px;padding:9px 15px;font:800 14px inherit;color:#527486;cursor:pointer}.tabs button[aria-selected=true]{border-color:#168b9e;background:#ddf5f5;color:#056f79}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:18px}.panel{border-radius:20px;padding:20px}.panel h2{margin:5px 0;font-size:19px;letter-spacing:-.02em}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:13px}.row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:11px;align-items:center;padding:11px 0;border-top:1px solid #e7eff3;font-size:14px}.row:first-child{border-top:0}.row a{color:#145d7d;text-decoration:none;font-weight:800}.pill{padding:5px 8px;border-radius:99px;background:#e8f3f8;color:#3f7089;font-size:11px;font-weight:900;white-space:nowrap}.empty{border:1px dashed #b9d4df;border-radius:12px;padding:15px;color:#5d7d8e;font-size:14px}.hidden{display:none!important}.calls-grid{display:grid;gap:10px}.call{border:1px solid var(--line);border-radius:14px;padding:14px;background:#fff}.call-top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.call h3{margin:0;font-size:15px}.call p{margin:7px 0 0;color:#678495;font-size:13px}.call a{color:#056e85;font-weight:800;text-decoration:none}.score-badge{min-width:48px;padding:7px;border-radius:10px;background:#e5f6f2;color:#007d7d;text-align:center;font-weight:900}.score-badge.none{background:#f1f4f5;color:#728894}.call-meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.call-meta span{font-size:11px;font-weight:800;color:#57788a;background:#f0f6f8;border-radius:8px;padding:5px 7px}.notice{padding:13px;border-radius:12px;background:#fff8e8;color:#74581e;font-size:13px;line-height:1.45}.loader{padding:28px;color:#547688;text-align:center;font-weight:700}@media(max-width:1050px){.shell{grid-template-columns:1fr}.rail{position:static}.nav{grid-template-columns:repeat(4,auto);overflow:auto}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.shell{padding:12px}.hero{padding:20px;display:block}.hero h1{font-size:28px}.actions{margin-top:15px}.kpis,.grid{grid-template-columns:1fr}.kpi{min-height:auto}.row{grid-template-columns:1fr auto}.row .pill:last-child{grid-column:2}.select{max-width:100%}}
</style></head><body><div class="shell"><aside class="rail"><div class="brand">MAVIS · моя работа</div><div class="avatar" id="avatar">—</div><h2 id="person">Загрузка…</h2><p class="muted" id="role">Личный кабинет</p><span class="identity" id="mode">Проверяю доступ</span><nav class="nav" aria-label="Разделы кабинета"><button data-tab="overview" aria-selected="true">Обзор работы</button><button data-tab="calls" aria-selected="false">Мои звонки</button></nav><p class="muted">Показаны только данные выбранного сотрудника. Руководитель может переключить просмотр на менеджера из состава продаж.</p></aside><main><header class="hero"><div><p class="eyebrow">Продажи · личный кабинет</p><h1 id="headline">Мой рабочий день</h1><p class="muted" id="subtitle">Загружаю данные Bitrix24 и Jarvis…</p></div><div class="actions"><select class="select hidden" id="manager-select" aria-label="Посмотреть от лица менеджера"></select><button class="button" id="refresh">Обновить</button></div></header><section class="kpis" id="kpis"><div class="loader">Загружаю показатели…</div></section><div class="tabs" role="tablist"><button data-tab="overview" aria-selected="true">Работа</button><button data-tab="calls" aria-selected="false">Мои звонки</button></div><section id="overview" class="tab"><div class="grid"><article class="panel"><div class="head"><div><p class="eyebrow">Воронка</p><h2>Сделки в работе</h2></div><span class="pill" id="deal-count"></span></div><div id="stages"></div></article><article class="panel"><div class="head"><div><p class="eyebrow">Очередь</p><h2>Дела и риски</h2></div></div><div id="tasks"></div></article></div><div class="grid" style="margin-top:18px"><article class="panel"><p class="eyebrow">Доход</p><h2 id="salary">Зарплата не настроена</h2><p class="muted" id="salary-note">Руководитель может задать личный план, базу и процент.</p></article><article class="panel"><p class="eyebrow">Подсказки</p><h2>Где нужна реакция</h2><div id="hints"></div></article></div></section><section id="calls" class="tab hidden"><article class="panel"><div class="head"><div><p class="eyebrow">Качество общения</p><h2>Мои звонки и разборы</h2><p class="muted">Карточка содержит оценку, рекомендацию и прямую ссылку на связанную сделку в Bitrix24.</p></div><span class="identity" id="calls-total">—</span></div><div id="calls-list" class="calls-grid"><div class="loader">Загружаю журнал звонков…</div></div></article></section></main></div><script>
let me,workday,calls,selectedId='',tab='overview';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(Number(v||0))+' BYN',qs=()=>selectedId?'?manager_id='+encodeURIComponent(selectedId):'';function row(x,label=''){return `<div class="row"><a target="_blank" rel="noopener" href="${esc(x.url||'#')}">${esc(x.title||'Без названия')}</a><span class="pill">${esc(label)}</span></div>`}function showTab(next){tab=next;$$('[data-tab]').forEach(x=>x.setAttribute('aria-selected',x.dataset.tab===tab));$('.tab#overview').classList.toggle('hidden',tab!=='overview');$('.tab#calls').classList.toggle('hidden',tab!=='calls')}async function load(){try{me=await (await fetch('/api/cabinet/me')).json();if(me.role==='director'){const roster=await (await fetch('/api/cabinet/managers')).json();const select=$('#manager-select');select.innerHTML=(roster.managers||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');selectedId=(roster.managers||[]).find(x=>x.name.includes('Хурсик'))?.id||roster.managers?.[0]?.id||me.user_id;select.value=selectedId;select.classList.remove('hidden')}const [wr,cr,sr]=await Promise.all([fetch('/api/cabinet/workday'+qs()),fetch('/api/cabinet/calls'+qs()),fetch('/api/cabinet/salary'+qs())]);workday=await wr.json();calls=await cr.json();const salary=await sr.json();if(!wr.ok)throw new Error(workday.detail||'Данные временно недоступны');render(salary)}catch(e){$('#subtitle').textContent=e.message||'Не удалось загрузить кабинет'}}function render(salary){const d=workday.deals,t=workday.tasks,callsData=calls.data||{},summary=callsData.summary||{},name=workday.profile?.name||'Менеджер';$('#person').textContent=name;$('#avatar').textContent=name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();$('#headline').textContent=me.role==='director'?'Просмотр: '+name:'Здравствуйте, '+name.split(' ')[0];$('#role').textContent=me.role==='director'?'Режим руководителя':'Менеджер по продажам';$('#mode').textContent=me.role==='director'?'Просмотр от лица менеджера':'Только мои данные';$('#subtitle').textContent='Факты Bitrix24 и Jarvis · отчётная дата '+workday.date;$('#kpis').innerHTML=[['Средняя оценка звонков',summary.averageScore==null?'Нет оценок':summary.averageScore+'/10',summary.scored+' оценок Jarvis'],['Сделки в работе',d.active_count,'разбивка по этапам ниже'],['Новые лиды',workday.leads.month_count,'с начала месяца'],['План / факт',money(salary.monthly_plan||0)+' / '+money(d.fact_amount),'успешные сделки месяца'],['Предплан',money(d.preplan_amount),d.preplan_count+' сделок на этапах 10–12'],['Успешные звонки',workday.calls.successful_from_minute+' / '+workday.calls.target,'длительность от минуты'],['Просрочено',t.overdue_count+' дел · '+d.overdue_count+' сделок','нужна реакция'],['Без дела',d.without_open_task_count,'без открытого дела']].map((x,i)=>`<article class="kpi ${i===0?'score':''}"><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></article>`).join('');$('#deal-count').textContent=d.active_count+' в работе';$('#stages').innerHTML=d.stages?.length?d.stages.map(x=>`<div class="row"><span>${esc(x.name)}</span><b>${x.count}</b><span class="pill">${money(x.amount)}</span></div>`).join(''):'<div class="empty">Открытых сделок нет.</div>';const tasks=[...t.today.map(x=>row(x,'сегодня')),...t.tomorrow.map(x=>row(x,'следующий рабочий день')),...t.overdue.slice(0,5).map(x=>row(x,'просрочено'))];$('#tasks').innerHTML=tasks.length?tasks.join(''):'<div class="empty">Открытых дел на ближайший рабочий день нет.</div>';const hints=[...d.without_open_task.slice(0,3).map(x=>row(x,'создайте дело')),...d.missing_source.slice(0,2).map(x=>row(x,'заполните источник')),...d.missing_client_type.slice(0,2).map(x=>row(x,'укажите тип клиента'))];$('#hints').innerHTML=hints.length?hints.join(''):'<div class="empty">Сделок без обязательного действия сейчас нет.</div>';$('#salary').textContent=salary.configured?money(salary.today_amount):'Зарплата не настроена';$('#salary-note').textContent=salary.configured?salary.formula:'Для этого сотрудника пока не заданы база, процент или план.';$('#calls-total').textContent=(summary.calls||0)+' звонков · '+(summary.scored||0)+' оценок';const rows=callsData.calls||[];$('#calls-list').innerHTML=rows.length?rows.map(x=>{const deal=x.dealId?`<a target="_blank" rel="noopener" href="${esc(me.portal)}/crm/deal/details/${esc(x.dealId)}/">Открыть сделку №${esc(x.dealId)}</a>`:'Связи со сделкой нет';return `<article class="call"><div class="call-top"><div><h3>${esc(x.client)}</h3><p>${esc(x.recommendation||'Разбор ещё не готов')}</p></div><span class="score-badge ${x.score==null?'none':''}">${x.score==null?'—':esc(x.score)}</span></div><div class="call-meta"><span>${esc(x.direction==='incoming'?'Входящий':'Исходящий')}</span><span>${Math.round(Number(x.durationSeconds||0)/60)} мин</span><span>${esc(x.stage||'Без стадии')}</span><span>${esc(x.created||'')}</span><span>${deal}</span></div></article>`}).join(''):'<div class="empty">У этого сотрудника пока нет звонков в Jarvis.</div>'}$('#refresh').onclick=load;$('#manager-select').onchange=e=>{selectedId=e.target.value;load()};$$('[data-tab]').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));load();
</script></body></html>"""
